DROP TABLE IF EXISTS `wp_posts`;
CREATE TABLE `wp_posts` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM;
ALTER TABLE wp_posts DEFAULT CHARACTER SET=utf8mb4 ENGINE=MyISAM;
CREATE TABLE a (id INT) PACK_KEYS=DEFAULT ENGINE=MyISAM;
CREATE TABLE b (id INT) UNION=(a,wp_posts) ENGINE=MRG_MYISAM;
ALTER TABLE wp_posts PACK_KEYS=DEFAULT ENGINE=Aria;
